from pathlib import Path
import base64,gzip
FILES={
'server/admin-ui.mjs':'''''',
'server/worker.mjs':'''''',
'tests/admin-console.test.js':'''''',
'tests/admin-worker.test.js':''''''
}
for path,payload in FILES.items():
    target=Path(path); target.parent.mkdir(parents=True,exist_ok=True); target.write_bytes(gzip.decompress(base64.b64decode(payload)))
